import{_ as a,C as s,o as n,c as i,aj as e,G as r}from"./chunks/framework.BwH0p-pt.js";const y=JSON.parse('{"title":"Product Associations","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/associations/index.md","filePath":"3.0/associations/index.md","lastUpdated":1785836850000}'),l={name:"3.0/associations/index.md"};function c(d,t,h,u,p,m){const o=s("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="product-associations" tabindex="-1">Product Associations <a class="header-anchor" href="#product-associations" aria-label="Permalink to &quot;Product Associations&quot;">​</a></h1><p>A <strong>product association</strong> links one product to another to tell a story your channels can use: <em>&quot;customers who look at this also want that&quot;</em>, <em>&quot;this is the premium alternative&quot;</em>, <em>&quot;these go together in the cart&quot;</em>. You maintain the links once in UnoPim, and every connected shop, marketplace or app receives them with the product.</p><p>UnoPim ships with three association types:</p><table tabindex="0"><thead><tr><th>Type</th><th>What it is for</th></tr></thead><tbody><tr><td><strong>Related Products</strong></td><td>Products shown alongside the one the customer is viewing.</td></tr><tr><td><strong>Up Sells</strong></td><td>A premium or higher-quality alternative to the current product.</td></tr><tr><td><strong>Cross Sells</strong></td><td>Complementary &quot;add this too&quot; products, typically shown near the cart.</td></tr></tbody></table><h2 id="new-in-3-0-your-own-association-types" tabindex="-1">New in 3.0: your own association types <a class="header-anchor" href="#new-in-3-0-your-own-association-types" aria-label="Permalink to &quot;New in 3.0: your own association types&quot;">​</a></h2><p>The three built-in types used to be the whole list. From UnoPim 3.0 they are just the starting point — you can create as many association types as your business needs: <em>Spare Parts</em>, <em>Accessories</em>, <em>Successor Model</em>, <em>Bundle Contents</em>, and so on.</p><p>Each type you create can carry:</p><ul><li>A <strong>localized label</strong> per catalog language, so every team sees it in their own words.</li><li>A <strong>status</strong> and a <strong>position</strong>, so you control which types are offered and in what order.</li><li>Optional <strong>custom fields</strong> on every product link — a quantity note, a &quot;featured&quot; flag — with per-language values where you need them.</li></ul>',8)),r(o,{src:"/assets/3.0/images/associations/associations-overview.png",alt:"Association types listing in the UnoPim admin"}),t[1]||(t[1]=e('<h2 id="why-associations-matter" tabindex="-1">Why associations matter <a class="header-anchor" href="#why-associations-matter" aria-label="Permalink to &quot;Why associations matter&quot;">​</a></h2><ul><li><strong>Merchandising</strong> — related, up-sell and cross-sell links drive the recommendation blocks on your storefronts.</li><li><strong>One source of truth</strong> — links are product data like any other: they travel through <a href="./../data-transfer/import.html">imports and exports</a> and are available to every integration.</li><li><strong>Structure, not free text</strong> — a link always points at a real product in your catalog, so it can never go stale silently.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Associations are directional. Linking a phone to a case does not link the case back to the phone — add the reverse link if both directions matter to you.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./association-types.html">Association Types</a> — create and manage the types themselves, including custom link fields.</li><li><a href="./linking-products.html">Linking Products</a> — attach associated products on the product edit page.</li></ul>',5))])}const _=a(l,[["render",c]]);export{y as __pageData,_ as default};
